//! Deterministic harness × feature matrix generator.
//!
//! Reads the real `IntegrationPort` implementations (capabilities, exposure
//! plans, package plans, runtime support, exposure names) and renders the
//! matrix + invocation examples into the marker block of the docs site's
//! `web/content/docs/reference/harnesses.mdx`:
//!
//! ```text
//! <!-- uze-matrix:start -->
//! ... generated by this binary; do not hand-edit ...
//! <!-- uze-matrix:end -->
//! ```
//!
//! and the same routes into `web/lib/harness-matrix.json`, which the landing
//! page's capability table renders.
//!
//! `--check` exits non-zero when either artifact is stale (wired into the
//! lefthook pre-push and `make harness-matrix`); without the flag it rewrites
//! them in place. Nothing here hardcodes a harness's capability claim — every
//! cell is derived from the code that implements it, so a capability change
//! that forgets the docs fails the push.

use std::path::{Path, PathBuf};

use uze_core::{
    PackageId, UzeHome,
    acquisition::{PackageSource, Provenance, ResolvedSource},
    capability::Resource,
    capability::{Capability, CapabilityKind},
    integration::{ContextDelivery, IntegrationPort, SessionContinuity},
    router::CompatibilityRoute,
    store::StoredPackage,
};
use uze_integrations::registry::IntegrationRegistry;

/// Planned harnesses: no `IntegrationPort` yet, so matrix cells would be
/// meaningless — listed as roadmap only, and they flip the moment they land.
const PLANNED_HARNESSES: [&str; 3] = ["Cursor CLI", "Muse", "PI"];

// MDX parses `<...>` as JSX, so an HTML comment (`<!-- -->`) is a syntax
// error there — the JSX comment form is what both Markdown and MDX render
// invisibly.
const MARKER_START: &str = "{/* uze-matrix:start */}";
const MARKER_END: &str = "{/* uze-matrix:end */}";
const HARNESS_DOCS: &str = "web/content/docs/reference/harnesses.mdx";
/// The same routes, for the landing page's capability table. One generator,
/// two consumers: the landing page used to restate delivery in hand-written
/// prose, which is a second place for the same claim to go stale.
/// One hand-written note per harness, by integration id, which its tab
/// includes; outside `content/docs` so none becomes a page of its own.
const NOTES_DIR: &str = "web/content/harness-notes";
const HARNESS_JSON: &str = "web/lib/harness-matrix.json";

fn route_symbol(route: CompatibilityRoute) -> &'static str {
    match route {
        CompatibilityRoute::Native => "🟢",
        CompatibilityRoute::Adaptable => "🟡",
        CompatibilityRoute::Degraded => "🟠",
        CompatibilityRoute::Unsupported => "⚪",
    }
}

fn route_of(integration: &dyn IntegrationPort, resource: &Resource) -> CompatibilityRoute {
    integration.exposure_plan(resource).route
}

/// The disposable package root carrying flow's canonical bytes — shared by
/// every resource and the stub package so plans correlate paths.
fn pkg_root() -> PathBuf {
    let root = std::env::temp_dir().join("uze-harness-matrix-pkg");
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(root.join("skills/commit")).unwrap();
    std::fs::write(
        root.join("plugin.json"),
        r#"{"$schema":"https://agent-plugins.org/schemas/1.0.0/plugin.schema.json","name":"flow"}"#,
    )
    .unwrap();
    std::fs::write(
        root.join("skills/commit/SKILL.md"),
        "---\nname: commit\ndescription: Matrix fixture skill.\n---\n\nBody.\n",
    )
    .unwrap();
    std::fs::write(
        root.join("mcp.json"),
        r#"{"mcpServers":{"conformance":{"command":"fixture","args":[]}}}"#,
    )
    .unwrap();
    std::fs::write(root.join(uze_core::hook::HOOKS_FILE_NAME), HOOKS_MANIFEST).unwrap();
    root
}

/// The authored hook manifest every hook cell is derived from. A real one:
/// a hook resource's payload *is* the normalized group (see the engine's
/// `hook_resources`), so a placeholder payload makes every integration's
/// plan fail to parse and report `Unsupported` — a shipped capability
/// documented as a roadmap gap.
///
/// `observe` is the portable baseline every harness can carry, so the cell
/// answers "does this harness deliver hooks at all". A blocking effect is
/// a per-effect question one column cannot hold — a `deny` group is
/// honestly unsupported on a harness whose hook point carries no block
/// signal — and belongs in the prose below the generated block.
const HOOKS_MANIFEST: &str = r#"{"hooks":{"PreToolUse":[{"id":"guard","matcher":"shell","effect":"observe","hooks":[{"type":"command","command":"./hooks/guard.sh"}]}]}}"#;

fn skill(payload: &str, name: &str) -> Resource {
    let root = pkg_root();
    Resource::from_package(
        PackageId::from_plugin_name("flow", &root.join("plugin.json")).unwrap(),
        root.clone(),
        Capability {
            kind: CapabilityKind::AgentSkill,
            path: root.join(format!("skills/{name}/SKILL.md")),
            payload: payload.as_bytes().to_vec(),
        },
    )
}

fn mcp() -> Resource {
    let root = pkg_root();
    Resource::from_package_named(
        PackageId::from_plugin_name("flow", &root.join("plugin.json")).unwrap(),
        root.clone(),
        Capability {
            kind: CapabilityKind::Mcp,
            path: root.join("mcp.json"),
            payload: br#"{"command":"fixture","args":[]}"#.to_vec(),
        },
        "conformance".to_owned(),
    )
}

/// One canonical hook group, materialized exactly as the engine does it:
/// parse the authored manifest, and carry the normalized group as the
/// resource payload.
fn hook() -> Resource {
    hook_group(HOOKS_MANIFEST)
}

/// One portable hook group as a resource of the fixture package: what the
/// hook tables ask each integration to plan.
fn hook_group(manifest_json: &str) -> Resource {
    let root = pkg_root();
    let manifest = root.join(uze_core::hook::HOOKS_FILE_NAME);
    let group = uze_core::hook::parse_manifest(&manifest, manifest_json.as_bytes())
        .expect("matrix hook manifest is valid")
        .remove(0);
    let name = group.id.clone();
    Resource::from_package_named(
        PackageId::from_plugin_name("flow", &root.join("plugin.json")).unwrap(),
        root,
        Capability {
            kind: CapabilityKind::Hook,
            path: manifest,
            payload: serde_json::to_vec(&group).expect("portable hook serializes"),
        },
        name,
    )
}

fn capability_resource(kind: CapabilityKind, path: &str) -> Resource {
    let root = pkg_root();
    Resource::from_package(
        PackageId::from_plugin_name("flow", &root.join("plugin.json")).unwrap(),
        root.clone(),
        Capability {
            kind,
            path: PathBuf::from(path),
            payload: Vec::new(),
        },
    )
}

fn stub_package() -> StoredPackage {
    let root = pkg_root();
    StoredPackage {
        id: PackageId::from_plugin_name("flow", &root.join("plugin.json")).unwrap(),
        active_name: "flow".to_owned(),
        root: root.clone(),
        manifest: root.join("plugin.json"),
        provenance: Provenance {
            requested: PackageSource::Local { path: root.clone() },
            resolved: ResolvedSource::Local { path: root },
        },
    }
}

fn package_route(integration: &dyn IntegrationPort) -> Option<CompatibilityRoute> {
    let package = stub_package();
    let skill = skill("-", "commit");
    let mcp = mcp();
    let resources: Vec<&Resource> = vec![&skill, &mcp];
    integration
        .package_exposure_plan(&package, &resources)
        .map(|plan| plan.route)
}

struct Harness {
    integration: Box<dyn IntegrationPort>,
}

/// Real setup state, like the L1 contract tests record before asking for
/// exposure plans: without it the integrations deliberately prefer the
/// unmanaged/adapted route, and the matrix would document the wrong
/// surface. Writes only inside the temp root.
fn mark_setup(home: &UzeHome, integration: &dyn IntegrationPort) {
    std::fs::create_dir_all(home.state_dir()).unwrap();
    uze_core::state::record(
        home,
        integration.id(),
        uze_core::state::IntegrationRecord {
            version: None,
            strategy: "harness-matrix".to_owned(),
        },
    )
    .unwrap();
}

fn harnesses() -> Vec<Harness> {
    let root = std::env::temp_dir().join(format!("uze-harness-matrix-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();
    let uze_home = UzeHome::at(root.join("uze"));
    let registry = IntegrationRegistry::isolated(&root, &uze_home);
    let integrations = registry.into_inner();
    for integration in &integrations {
        mark_setup(&uze_home, integration.as_ref());
    }
    integrations
        .into_iter()
        .map(|integration| Harness { integration })
        .collect()
}

/// Effective delivery route for a resource: the native package plan's route
/// when the plan both exists and covers the resource's identity, otherwise
/// the capability-level (fallback) route the integration actually uses.
fn effective_route(
    integration: &dyn IntegrationPort,
    resource: &Resource,
    fallback: CompatibilityRoute,
) -> CompatibilityRoute {
    let package = stub_package();
    if let Some(plan) = integration.package_exposure_plan(&package, &[resource])
        && plan.route == CompatibilityRoute::Native
        && plan
            .provided_resource_identities
            .contains(&resource.identity())
    {
        return CompatibilityRoute::Native;
    }
    fallback
}

/// The name cell both generated tables open with: the harness's mark, its
/// name, and — where the vendor has a public home — a link to it, opened in
/// a tab of its own so a reader chasing "what is Antigravity" does not lose
/// the page they were reading.
///
/// Raw HTML in MDX is parsed as JSX, not HTML — `style` must be an object
/// there, so a plain CSS string 500s the build. className
/// (harness-table-icon/-cell, styled in app/global.css) instead. The icon
/// and name are wrapped in one inline-flex element so they never wrap onto
/// separate lines in a narrow column.
fn harness_cell(integration: &dyn IntegrationPort) -> String {
    let name = integration.display_name();
    let icon = integration
        .icon_path()
        .map(|icon| format!("<img src=\"{icon}\" alt=\"\" className=\"harness-table-icon\" />"))
        .unwrap_or_default();
    match integration.homepage() {
        Some(homepage) => format!(
            "<a className=\"harness-table-cell\" href=\"{homepage}\" target=\"_blank\" rel=\"noreferrer noopener\">{icon}{name}</a>"
        ),
        None if icon.is_empty() => name.to_owned(),
        None => format!("<span className=\"harness-table-cell\">{icon}{name}</span>"),
    }
}

/// Whether an agent's conversation is carried over on this harness, read
/// off the integration's own declaration. Naming a conversation before it
/// starts and reading the name back afterwards are both native — the
/// harness's own documented verbs, no adaptation — so the cell answers
/// "does a relaunch continue here", not which of the two mechanisms it took.
fn continuity_symbol(integration: &dyn IntegrationPort) -> &'static str {
    match integration.session_continuity() {
        SessionContinuity::Assigned | SessionContinuity::Observed => "🟢",
        SessionContinuity::Unsupported => "⚪",
    }
}

/// The fixture resources every table asks the integrations about.
struct Fixtures {
    default_skill: Resource,
    user_only_skill: Resource,
    model_only_skill: Resource,
    mcp: Resource,
    agents: Resource,
    hooks: Resource,
}

impl Fixtures {
    fn new() -> Self {
        Self {
            default_skill: skill(
                "---\nname: commit\ndescription: Matrix fixture skill.\n---\n\nBody.\n",
                "commit",
            ),
            user_only_skill: skill(
                "---\nname: review\ndescription: Matrix fixture skill.\ninvoke:\n  model: false\n  user: true\n---\n\nBody.\n",
                "review",
            ),
            model_only_skill: skill(
                "---\nname: analyze\ndescription: Matrix fixture skill.\ninvoke:\n  model: true\n  user: false\n---\n\nBody.\n",
                "analyze",
            ),
            mcp: mcp(),
            agents: capability_resource(CapabilityKind::Agent, "/store/flow/agents/planner.md"),
            hooks: hook(),
        }
    }

    /// The four capabilities a plugin carries, by name.
    fn capabilities(&self) -> [(&'static str, &Resource); 4] {
        [
            ("Skills", &self.default_skill),
            ("Agents", &self.agents),
            ("MCP", &self.mcp),
            ("Hooks", &self.hooks),
        ]
    }
}

/// A resource's route as the install takes it: the package plan's where it
/// carries the resource, the capability's own otherwise.
fn delivered(integration: &dyn IntegrationPort, resource: &Resource) -> CompatibilityRoute {
    effective_route(integration, resource, route_of(integration, resource))
}

/// The first sentence of why a delivery is adapted or lossy, read from the
/// integration's own plan; nothing for a native one.
fn why(integration: &dyn IntegrationPort, resource: &Resource) -> String {
    let route = delivered(integration, resource);
    if route == CompatibilityRoute::Native {
        return String::new();
    }
    // An adapted route's evidence is written for whoever maintains the
    // adapter; the reader is told only that UZE carries it, and the
    // harness's note says how.
    if route == CompatibilityRoute::Adaptable {
        return "adapted by UZE, as the note above describes".to_owned();
    }
    let evidence = integration.exposure_plan(resource).evidence;
    evidence
        .split_inclusive(". ")
        .next()
        .unwrap_or(&evidence)
        .trim()
        .trim_end_matches('.')
        .replace('|', "\\|")
}

/// Which capabilities ride the harness's own plugin, and which UZE delivers
/// beside it; the plugin system named, or `None` without one.
fn arrival(
    integration: &dyn IntegrationPort,
    fixtures: &Fixtures,
) -> (Option<&'static str>, Vec<&'static str>, Vec<&'static str>) {
    let capabilities = fixtures.capabilities();
    let resources: Vec<&Resource> = capabilities.iter().map(|(_, resource)| *resource).collect();
    let plan = integration.package_exposure_plan(&stub_package(), &resources);
    let system = plan.as_ref().map(|plan| match plan.envelope {
        uze_core::exposure::PackageEnvelope::Own => {
            "its own plugin, from a UZE-managed marketplace"
        }
        uze_core::exposure::PackageEnvelope::Generated => "a plugin UZE generates from the package",
    });
    let carried = |resource: &Resource| plan.as_ref().is_some_and(|plan| plan.provides(resource));
    let through = capabilities
        .iter()
        .filter(|(_, resource)| carried(resource))
        .map(|(name, _)| *name)
        .collect();
    let beside = capabilities
        .iter()
        .filter(|(_, resource)| !carried(resource))
        .map(|(name, _)| *name)
        .collect();
    (system, through, beside)
}

/// The hook rows the per-harness tab and the comparison both read: a label
/// and the manifest of a group of that shape.
fn hook_events() -> Vec<(&'static str, String)> {
    vec![
        ("`PreToolUse`", hook_manifest("PreToolUse", "", "observe")),
        ("`PostToolUse`", hook_manifest("PostToolUse", "", "observe")),
        ("`Stop`", hook_manifest("Stop", "", "observe")),
        (
            "`SessionStart` (new session)",
            hook_manifest("SessionStart", "startup", "observe"),
        ),
        (
            "`SessionStart` (resumed session)",
            hook_manifest("SessionStart", "resume", "observe"),
        ),
    ]
}

fn hook_effects() -> Vec<(&'static str, String)> {
    ["observe", "allow", "deny", "ask", "transform"]
        .into_iter()
        .map(|effect| {
            let label = match effect {
                "observe" => "`observe`",
                "allow" => "`allow`",
                "deny" => "`deny`",
                "ask" => "`ask`",
                _ => "`transform`",
            };
            (label, hook_manifest("PreToolUse", "shell", effect))
        })
        .collect()
}

fn hook_tools() -> Vec<(&'static str, String)> {
    [
        ("`shell`", "shell"),
        ("`file.read`", "file.read"),
        ("`file.write`", "file.write"),
        ("`file.edit`", "file.edit"),
        ("`search.files`", "search.files"),
        ("`search.web`", "search.web"),
        ("`agent.spawn`", "agent.spawn"),
        ("`agent.message`", "agent.message"),
    ]
    .into_iter()
    .map(|(label, alias)| (label, hook_manifest("PreToolUse", alias, "observe")))
    .collect()
}

/// The labels of `rows` this harness carries, and those it does not.
fn split_hooks(
    integration: &dyn IntegrationPort,
    rows: &[(&'static str, String)],
) -> (Vec<&'static str>, Vec<&'static str>) {
    let mut yes = Vec::new();
    let mut no = Vec::new();
    for (label, manifest) in rows {
        match route_of(integration, &hook_group(manifest)) {
            CompatibilityRoute::Native | CompatibilityRoute::Adaptable => yes.push(*label),
            _ => no.push(*label),
        }
    }
    (yes, no)
}

/// `a`, `a and b`, `a, b and c`: a list as a sentence reads it.
fn in_prose(labels: &[&str]) -> String {
    let labels: Vec<String> = labels
        .iter()
        .map(|label| {
            if *label == "MCP" {
                "MCP servers".to_owned()
            } else {
                label.to_lowercase()
            }
        })
        .collect();
    match labels.split_last() {
        None => String::new(),
        Some((last, [])) => last.clone(),
        Some((last, rest)) => format!("{} and {last}", rest.join(", ")),
    }
}

fn listed(labels: &[&str]) -> String {
    if labels.is_empty() {
        "—".to_owned()
    } else {
        labels.join(", ")
    }
}

/// One harness's tab: everything about it in one place.
fn harness_tab(integration: &dyn IntegrationPort, fixtures: &Fixtures) -> String {
    let name = integration.display_name();
    let mut out = format!("  <Tab value=\"{}\">\n\n", integration.id());

    let (system, through, beside) = arrival(integration, fixtures);
    out.push_str(&match system {
        Some(system) => format!(
            "A plugin reaches {name} through {system}, which carries its {}. {}\n\n",
            in_prose(&through),
            if beside.is_empty() {
                "Nothing goes beside it.".to_owned()
            } else {
                format!(
                    "UZE delivers its {} beside it, to {name}'s own native surfaces.",
                    in_prose(&beside)
                )
            }
        ),
        None => format!(
            "{name} has no plugin system: UZE delivers every capability to {name}'s own \
             native surfaces, and installs, updates and removes each one.\n\n"
        ),
    });

    if Path::new(NOTES_DIR)
        .join(format!("{}.mdx", integration.id()))
        .exists()
    {
        out.push_str(&format!(
            "<include>../../harness-notes/{}.mdx</include>\n\n",
            integration.id()
        ));
    }

    // Wrapped so every tab's table takes the same column widths
    // (`.harness-capabilities` in app/global.css) whatever its content.
    out.push_str(
        "<div className=\"harness-capabilities\">\n\n| Capability | | How |\n| --- | --- | --- |\n",
    );
    let row = |label: &str, route: CompatibilityRoute, why: String| {
        let how = if why.is_empty() {
            match route {
                CompatibilityRoute::Native => "native".to_owned(),
                CompatibilityRoute::Adaptable => "adapted by UZE".to_owned(),
                _ => "not available".to_owned(),
            }
        } else {
            why
        };
        format!("| {label} | {} | {how} |\n", route_symbol(route))
    };
    for (label, resource) in fixtures.capabilities() {
        if label == "Hooks" {
            continue;
        }
        out.push_str(&row(
            label,
            delivered(integration, resource),
            why(integration, resource),
        ));
    }
    out.push_str(&row(
        "Skill: person only",
        delivered(integration, &fixtures.user_only_skill),
        why(integration, &fixtures.user_only_skill),
    ));
    out.push_str(&row(
        "Skill: model only",
        delivered(integration, &fixtures.model_only_skill),
        why(integration, &fixtures.model_only_skill),
    ));
    out.push_str(&row(
        "Hooks",
        route_of(integration, &fixtures.hooks),
        why(integration, &fixtures.hooks),
    ));
    let context = match integration.context_delivery() {
        ContextDelivery::Bridge { file_name } => {
            format!("read through the `{file_name}` bridge (`@AGENTS.md`)")
        }
        _ => "read natively".to_owned(),
    };
    out.push_str(&format!("| Project `AGENTS.md` | 🟢 | {context} |\n"));
    out.push_str(&format!(
        "| Workspace: resume a relaunched agent | {} | |\n",
        continuity_symbol(integration)
    ));

    out.push_str("\n</div>\n");

    let (events, no_events) = split_hooks(integration, &hook_events());
    let (effects, no_effects) = split_hooks(integration, &hook_effects());
    let (tools, no_tools) = split_hooks(integration, &hook_tools());
    out.push_str(&format!(
        "\n**Hooks**\n\n\
         - Runs on: {}\n\
         - Can decide: {}\n\
         - Reaches: {}\n",
        listed(&events),
        listed(&effects),
        listed(&tools),
    ));
    let missing: Vec<&str> = no_events
        .iter()
        .chain(&no_effects)
        .chain(&no_tools)
        .copied()
        .collect();
    if !missing.is_empty() {
        out.push_str(&format!("- Not available here: {}\n", missing.join(", ")));
    }

    let prefix = integration.invocation_prefix();
    let first_name = |resource: &Resource, fallback: &str| {
        integration
            .exposure_name_candidates(resource)
            .into_iter()
            .next()
            .unwrap_or_else(|| fallback.to_owned())
    };
    out.push_str(&format!(
        "\n**Invoking a plugin's skill:** `{prefix}{}`\n",
        first_name(&fixtures.default_skill, "commit")
    ));

    let facts = integration.facts();
    if !facts.is_empty() {
        out.push_str(
            "\n**Measured in the Conformance Lab**\n\n\
             <div className=\"harness-facts\">\n\n\
             | About | Fact | Measured on |\n| --- | --- | --- |\n",
        );
        for fact in facts {
            out.push_str(&format!(
                "| {} | {} | {} |\n",
                fact.subject,
                fact.fact.replace('|', "\\|"),
                fact.measured_on,
            ));
        }
    }
    if !facts.is_empty() {
        out.push_str("\n</div>\n");
    }
    out.push_str("\n  </Tab>\n");
    out
}

fn matrix_block() -> String {
    let fixtures = Fixtures::new();
    let harnesses = harnesses();
    let mut out = format!(
        "{MARKER_START}\n\
         {{/* Generated by `cargo run --bin uze-harness-matrix`; do not hand-edit. */}}\n\n\
         🟢 native · 🟡 adapted by UZE · 🟠 delivered with a stated loss · — not available\n\n\
         ### At a glance\n\n\
         | Harness | Plugin arrives through | Skills | Agents | MCP | Hooks |\n\
         | --- | --- | --- | --- | --- | --- |\n"
    );
    for harness in &harnesses {
        let integration = harness.integration.as_ref();
        let (system, _, beside) = arrival(integration, &fixtures);
        let route = match system {
            Some(_) if beside.is_empty() => "its own plugin",
            Some(_) => "its own plugin + UZE",
            None => "UZE",
        };
        out.push_str(&format!(
            "| {} | {route} | {} | {} | {} | {} |\n",
            harness_cell(integration),
            route_symbol(delivered(integration, &fixtures.default_skill)),
            route_symbol(delivered(integration, &fixtures.agents)),
            route_symbol(delivered(integration, &fixtures.mcp)),
            route_symbol(route_of(integration, &fixtures.hooks)),
        ));
    }

    // `items` takes plain strings, so the triggers are spelled out to carry
    // each harness's mark beside its name.
    let first = harnesses
        .first()
        .map(|harness| harness.integration.id())
        .unwrap_or_default();
    out.push_str(&format!(
        "\n### By harness\n\n<Tabs defaultValue=\"{first}\">\n  <TabsList>\n"
    ));
    for harness in &harnesses {
        let integration = harness.integration.as_ref();
        let icon = integration
            .icon_path()
            .map(|icon| format!("<img src=\"{icon}\" alt=\"\" className=\"harness-table-icon\" />"))
            .unwrap_or_default();
        out.push_str(&format!(
            "    <TabsTrigger value=\"{}\">{icon}{}</TabsTrigger>\n",
            integration.id(),
            integration.display_name()
        ));
    }
    out.push_str("  </TabsList>\n");
    for harness in &harnesses {
        out.push_str(&harness_tab(harness.integration.as_ref(), &fixtures));
    }
    out.push_str("</Tabs>\n\n");

    out.push_str(&compare_all(&harnesses, &fixtures));

    out.push_str("\n### Planned harnesses\n\n| Harness | Status |\n| --- | --- |\n");
    for planned in PLANNED_HARNESSES {
        out.push_str(&format!("| {planned} | ⚪ roadmap |\n"));
    }
    out.push_str(&format!("\n{MARKER_END}\n"));
    out
}

/// The cross-harness tables, folded: for comparing, not for a first read.
fn compare_all(harnesses: &[Harness], fixtures: &Fixtures) -> String {
    let header = |first: &str| {
        let mut row = format!("| {first} |");
        let mut rule = String::from("| --- |");
        for harness in harnesses {
            row.push_str(&format!(" {} |", harness.integration.display_name()));
            rule.push_str(" --- |");
        }
        format!("{row}\n{rule}\n")
    };
    let resource_row = |label: &str, cell: &dyn Fn(&dyn IntegrationPort) -> String| {
        let mut line = format!("| {label} |");
        for harness in harnesses {
            line.push_str(&format!(" {} |", cell(harness.integration.as_ref())));
        }
        line.push('\n');
        line
    };
    let hook_rows = |rows: Vec<(&'static str, String)>| {
        let mut table = String::new();
        for (label, manifest) in rows {
            let resource = hook_group(&manifest);
            table.push_str(&resource_row(label, &|integration| {
                hook_cell(route_of(integration, &resource)).to_owned()
            }));
        }
        table
    };

    let mut out = String::from("### Compare all harnesses\n\n<Accordions>\n");

    out.push_str("<Accordion title=\"How a plugin arrives\">\n\n");
    out.push_str(&header("Capability"));
    for (label, resource) in fixtures.capabilities() {
        out.push_str(&resource_row(label, &|integration| {
            let carried = integration
                .package_exposure_plan(&stub_package(), &[resource])
                .is_some_and(|plan| plan.provides(resource));
            if carried { "its plugin" } else { "UZE" }.to_owned()
        }));
    }
    out.push_str("\n</Accordion>\n");

    out.push_str("<Accordion title=\"Who may invoke a skill\">\n\n");
    out.push_str(&header("Rule"));
    for (label, resource) in [
        ("Model and person (default)", &fixtures.default_skill),
        ("Person only", &fixtures.user_only_skill),
        ("Model only", &fixtures.model_only_skill),
    ] {
        out.push_str(&resource_row(label, &|integration| {
            route_symbol(delivered(integration, resource)).to_owned()
        }));
    }
    out.push_str("\n</Accordion>\n");

    out.push_str("<Accordion title=\"When a hook runs\">\n\n");
    out.push_str(&header("Event"));
    out.push_str(&hook_rows(hook_events()));
    out.push_str("\n</Accordion>\n");

    out.push_str("<Accordion title=\"What a PreToolUse hook can decide\">\n\n");
    out.push_str(&header("Effect"));
    out.push_str(&hook_rows(hook_effects()));
    out.push_str("\n</Accordion>\n");

    out.push_str("<Accordion title=\"Which tools a hook matcher reaches\">\n\n");
    out.push_str(&header("Alias"));
    out.push_str(&hook_rows(hook_tools()));
    out.push_str("\n</Accordion>\n");

    out.push_str("<Accordion title=\"Workspace\">\n\n");
    out.push_str(&header("Feature"));
    out.push_str(&resource_row(
        "Resumes a relaunched agent",
        &|integration| continuity_symbol(integration).to_owned(),
    ));
    out.push_str(&resource_row(
        "Project context through the shim (experimental)",
        &|integration| {
            if integration.supports_runtime_integration() {
                "🧪"
            } else {
                "—"
            }
            .to_owned()
        },
    ));
    out.push_str("\n</Accordion>\n");

    out.push_str("</Accordions>\n");
    out
}

/// A hook group on `event`, matching `matcher` (none when empty), with
/// `effect`, as a manifest's JSON.
fn hook_manifest(event: &str, matcher: &str, effect: &str) -> String {
    let matcher = if matcher.is_empty() {
        String::new()
    } else {
        format!(r#""matcher":"{matcher}","#)
    };
    format!(
        r#"{{"hooks":{{"{event}":[{{"id":"probe",{matcher}"effect":"{effect}","hooks":[{{"type":"command","command":"./hooks/probe.sh"}}]}}]}}}}"#
    )
}

/// A route as a hook table cell: delivered natively or through UZE's
/// adapter, or not at all.
fn hook_cell(route: CompatibilityRoute) -> &'static str {
    match route {
        CompatibilityRoute::Native => "🟢",
        CompatibilityRoute::Adaptable => "🟡",
        _ => "—",
    }
}

fn route_name(route: CompatibilityRoute) -> &'static str {
    match route {
        CompatibilityRoute::Native => "native",
        CompatibilityRoute::Adaptable => "adapted",
        CompatibilityRoute::Degraded => "degraded",
        CompatibilityRoute::Unsupported => "none",
    }
}

/// The landing page's table, as data. Deliberately a subset of the docs
/// matrix: the columns a reader weighs before installing, not every column
/// the reference needs.
/// The same declaration the matrix cell is derived from, named for the
/// landing table.
fn continuity_name(integration: &dyn IntegrationPort) -> &'static str {
    match integration.session_continuity() {
        SessionContinuity::Assigned | SessionContinuity::Observed => "native",
        SessionContinuity::Unsupported => "none",
    }
}

fn matrix_json() -> String {
    let default_skill = skill(
        "---\nname: commit\ndescription: Matrix fixture skill.\n---\n\nBody.\n",
        "commit",
    );
    let mcp = mcp();
    let agents = capability_resource(CapabilityKind::Agent, "/store/flow/agents/planner.md");
    let hooks = hook();

    let mut rows = Vec::new();
    for harness in harnesses() {
        let integration = harness.integration.as_ref();
        let context = match integration.context_delivery() {
            ContextDelivery::Bridge { .. } => "bridge",
            _ => "native",
        };
        let package = package_route(integration).map(route_name).unwrap_or("none");
        rows.push(format!(
            "    {{\n      \"name\": {},\n      \"icon\": {},\n      \"url\": {},\n      \"context\": \"{context}\",\n      \"skills\": \"{}\",\n      \"mcp\": \"{}\",\n      \"agents\": \"{}\",\n      \"hooks\": \"{}\",\n      \"session\": \"{}\",\n      \"package\": \"{package}\"\n    }}",
            json_string(integration.display_name()),
            match integration.icon_path() {
                Some(icon) => json_string(icon),
                None => "null".to_owned(),
            },
            match integration.homepage() {
                Some(homepage) => json_string(homepage),
                None => "null".to_owned(),
            },
            route_name(effective_route(
                integration,
                &default_skill,
                route_of(integration, &default_skill)
            )),
            route_name(effective_route(integration, &mcp, route_of(integration, &mcp))),
            route_name(route_of(integration, &agents)),
            route_name(route_of(integration, &hooks)),
            continuity_name(integration),
        ));
    }

    let planned = PLANNED_HARNESSES
        .iter()
        .map(|name| json_string(name))
        .collect::<Vec<_>>()
        .join(", ");

    format!(
        "{{\n  \"_generated\": \"cargo run --bin uze-harness-matrix — do not hand-edit\",\n  \"harnesses\": [\n{}\n  ],\n  \"planned\": [{planned}]\n}}\n",
        rows.join(",\n")
    )
}

fn json_string(value: &str) -> String {
    format!("\"{}\"", value.replace('\\', "\\\\").replace('"', "\\\""))
}

fn replace_block(contents: &str, block: &str) -> String {
    let start = contents
        .find(MARKER_START)
        .expect("target file must contain the uze-matrix marker block");
    let end = contents
        .find(MARKER_END)
        .map(|position| position + MARKER_END.len())
        .expect("target file must close the uze-matrix marker block");
    // The block carries its own trailing `\n`; the tail after the closing
    // marker starts with the `\n` the previous generation left behind —
    // strip exactly one so repeated runs are byte-idempotent.
    let tail = &contents[end..];
    let tail = tail.strip_prefix('\n').unwrap_or(tail);
    format!("{}{}{}", &contents[..start], block, tail)
}

/// Writes `contents` to `path` unless it is already what is there; under
/// `--check` a difference is a stale artifact and fails instead.
fn sync(path: &str, contents: &str, check: bool) -> bool {
    let current = std::fs::read_to_string(path).unwrap_or_default();
    if current == contents {
        return false;
    }
    if check {
        eprintln!("{path} is stale — run `make harness-matrix` and commit.");
        std::process::exit(1);
    }
    std::fs::write(path, contents).unwrap_or_else(|error| panic!("{path} is writable: {error}"));
    println!("updated {path}");
    true
}

fn main() {
    let check = std::env::args().any(|argument| argument == "--check");
    let block = matrix_block();
    let doc = std::fs::read_to_string(HARNESS_DOCS).expect("harnesses.mdx is readable");
    let expected = replace_block(&doc, &block);
    let json_changed = sync(HARNESS_JSON, &matrix_json(), check);
    if doc != expected {
        if check {
            eprintln!(
                "{HARNESS_DOCS} harness matrix is stale — run `make harness-matrix` and commit."
            );
            std::process::exit(1);
        }
        std::fs::write(HARNESS_DOCS, expected).expect("harnesses.mdx is writable");
        println!("updated {HARNESS_DOCS} harness matrix");
    } else if !check && !json_changed {
        println!("{HARNESS_DOCS} harness matrix is up to date");
    }
}
